-- =====================================================
-- VIGNETTE DS4: CALIBRATE THE ATTRITION MODEL AND PREDICT CUSTOMER MARGIN   (~45 min)
-- Persona:  Data Scientist
-- Question: "Are DS1's churn scores real probabilities, and how much will each
--            customer be worth over the next few months?"
-- Prereq:   DS1, or setup/catchup/ds1_model.sql
-- In the lab you build this in notebooks/ds4_customer_value.ipynb with Cortex Code; the models
-- are trained by vignettes/ds4_customer_value/ds4_reference.py. This file is the SQL answer key.
-- =====================================================

USE ROLE HOL_PARTICIPANT;
USE WAREHOUSE BANKING_WH;
USE SCHEMA BANKING_HOL.ML;

-- 1. score_check: DS1's scores against what really happened, by decile
WITH d AS (SELECT NTILE(10) OVER (ORDER BY s.CHURN_PROBABILITY) AS DECILE, s.CHURN_PROBABILITY, f.CHURNED_NEXT_3M
           FROM RB_ATTRITION_SCORES s JOIN RB_CHURN_FEATURES f USING (CUSTOMER_ID))
SELECT DECILE, COUNT(*) AS CUSTOMERS, ROUND(AVG(CHURN_PROBABILITY), 3) AS AVG_SCORE, ROUND(AVG(CHURNED_NEXT_3M), 4) AS ACTUALLY_LEFT
FROM d GROUP BY 1 ORDER BY 1;

-- 2. and 3. the experiments and the registry
SHOW RUNS IN EXPERIMENT RB_ATTRITION;
SHOW RUNS IN EXPERIMENT RB_MARGIN;
SHOW VERSIONS IN MODEL RB_ATTRITION_MODEL;
SHOW VERSIONS IN MODEL RB_MARGIN_MODEL;

-- 4. prediction_summary
SELECT COUNT(*) AS CUSTOMERS, ROUND(AVG(p.CHURN_3M), 4) AS AVG_CHANCE_OF_LEAVING, ROUND(AVG(f.CHURNED_NEXT_3M), 4) AS ACTUALLY_LEFT,
       ROUND(SUM(p.PREDICTED_MONTHLY_MARGIN_GBP)) AS PREDICTED_MONTHLY_MARGIN_GBP
FROM RB_CUSTOMER_PREDICTIONS p JOIN RB_CHURN_FEATURES f USING (CUSTOMER_ID);

-- =====================================================
-- APP1: BUILD AND SHIP THE FRAUD INVESTIGATOR APP - reference SQL
-- The app itself is built in a workspace (streamlit_app.py, pyproject.toml).
-- This file deploys the reference version the same way, as HOL_PARTICIPANT,
-- for facilitators or anyone who can't use Workspaces, then checks it.
-- =====================================================
USE SECONDARY ROLES NONE;
USE WAREHOUSE BANKING_WH;
USE SCHEMA BANKING_HOL.APPS;

-- 1. Upload the two files from this folder to a stage (Snowsight: Data > Add data, or snow stage copy)
CREATE STAGE IF NOT EXISTS APP1_SOURCE COMMENT = 'APP1: fraud investigator app source';
-- From the lab repository (or upload them: PUT file://streamlit_app.py @APP1_SOURCE AUTO_COMPRESS = FALSE OVERWRITE = TRUE;)
COPY FILES INTO @APP1_SOURCE
  FROM @BANKING_HOL_SETUP.PUBLIC.HOL_REPO/branches/main/vignettes/app1_fraud_investigator_app/
  FILES = ('streamlit_app.py', 'pyproject.toml');

-- 2. Create the app on the container runtime and publish it
CREATE OR REPLACE STREAMLIT FRAUD_INVESTIGATOR
    FROM @APP1_SOURCE
    MAIN_FILE = 'streamlit_app.py'
    TITLE = 'Fraud investigator'
    QUERY_WAREHOUSE = BANKING_WH
    COMPUTE_POOL = HOL_COMPUTE_POOL_CPU
    RUNTIME_NAME = 'SYSTEM$ST_CONTAINER_RUNTIME_PY3_11'
    EXTERNAL_ACCESS_INTEGRATIONS = (PYPI_ACCESS_INTEGRATION);
ALTER STREAMLIT FRAUD_INVESTIGATOR ADD LIVE VERSION FROM LAST;

-- 3. Share it view-only
GRANT USAGE ON STREAMLIT FRAUD_INVESTIGATOR TO ROLE HOL_RESTRICTED;

-- 4. Check: the app exists, and decisions are being saved
SHOW STREAMLITS LIKE 'FRAUD_INVESTIGATOR' IN SCHEMA BANKING_HOL.APPS;
SELECT DECISION, COUNT(*) AS DECISIONS, MAX(DECIDED_AT) AS LATEST, ANY_VALUE(DECIDED_BY) AS BY_SOMEONE
FROM MATCH_DECISIONS GROUP BY 1;

-- =====================================================
-- VIGNETTE GOV1: CLASSIFY, TAG, MASK AND FILTER PII   (~45 min)
-- Persona: Governance / Risk / Data Owner
-- Question: "Prove that account identifiers are protected wherever they flow -
--            dashboards, semantic views and AI agents - and that people only
--            see the clients in their region."
-- Prereq:   setup/catchup/core_analytics.sql (STG_ACCOUNTS, STG_CUSTOMERS)
-- Uses:     HOL_RESTRICTED role (granted to HOL_PARTICIPANT) to test as a consumer
-- =====================================================

USE ROLE HOL_PARTICIPANT;
USE SECONDARY ROLES NONE;   -- see exactly what an attendee sees
USE WAREHOUSE BANKING_WH;
USE SCHEMA BANKING_HOL.GOVERNANCE;

-- Reset (makes this script safe to run first time and to re-run)
CREATE TAG IF NOT EXISTS DATA_SENSITIVITY;
CREATE MASKING POLICY IF NOT EXISTS MASK_RESTRICTED_STRING AS (VAL STRING) RETURNS STRING -> VAL;
ALTER TAG DATA_SENSITIVITY UNSET MASKING POLICY MASK_RESTRICTED_STRING;
DROP TABLE IF EXISTS ACCOUNT_REGISTER;

-- -----------------------------------------------------
-- GOV1.1 Let Snowflake find the sensitive data
-- -----------------------------------------------------
CREATE OR REPLACE TABLE ACCOUNT_REGISTER AS
SELECT * FROM BANKING_HOL.ANALYTICS.STG_ACCOUNTS;   -- governed copy we own, for the lab

CALL SYSTEM$CLASSIFY('BANKING_HOL.GOVERNANCE.ACCOUNT_REGISTER', {'auto_tag': true});

SELECT COLUMN_NAME, TAG_NAME, TAG_VALUE
FROM TABLE(BANKING_HOL.INFORMATION_SCHEMA.TAG_REFERENCES_ALL_COLUMNS(
        'BANKING_HOL.GOVERNANCE.ACCOUNT_REGISTER', 'table'))
ORDER BY COLUMN_NAME;

-- -----------------------------------------------------
-- GOV1.2 The bank's own tag taxonomy
-- -----------------------------------------------------
CREATE OR REPLACE TAG DATA_SENSITIVITY
    ALLOWED_VALUES 'PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED'
    COMMENT = 'Bank-style data sensitivity classification';

ALTER TABLE ACCOUNT_REGISTER MODIFY COLUMN IBAN           SET TAG DATA_SENSITIVITY = 'RESTRICTED';
ALTER TABLE ACCOUNT_REGISTER MODIFY COLUMN ACCOUNT_NUMBER SET TAG DATA_SENSITIVITY = 'RESTRICTED';
ALTER TABLE ACCOUNT_REGISTER MODIFY COLUMN SORT_CODE      SET TAG DATA_SENSITIVITY = 'CONFIDENTIAL';
ALTER TABLE ACCOUNT_REGISTER MODIFY COLUMN BIC            SET TAG DATA_SENSITIVITY = 'INTERNAL';

-- -----------------------------------------------------
-- GOV1.3 Tag-based masking: protect every column carrying the tag, now and in future
-- -----------------------------------------------------
CREATE OR REPLACE MASKING POLICY MASK_RESTRICTED_STRING AS (VAL STRING) RETURNS STRING ->
    CASE
        WHEN IS_ROLE_IN_SESSION('HOL_ADMIN') THEN VAL                              -- data owner
        WHEN SYSTEM$GET_TAG_ON_CURRENT_COLUMN('BANKING_HOL.GOVERNANCE.DATA_SENSITIVITY') = 'CONFIDENTIAL'
             THEN REGEXP_REPLACE(VAL, '[0-9]', '*')                                 -- shape kept, digits hidden
        WHEN VAL IS NULL THEN NULL
        ELSE '****' || RIGHT(VAL, 4)                                               -- last 4 only
    END
    COMMENT = 'Masks RESTRICTED/CONFIDENTIAL strings for everyone except the data owner';

ALTER TAG DATA_SENSITIVITY SET MASKING POLICY MASK_RESTRICTED_STRING;
-- Note: the policy applies to every tagged value; INTERNAL and PUBLIC columns
-- fall through to last-4 here - refine the CASE for your own taxonomy.
ALTER TABLE ACCOUNT_REGISTER MODIFY COLUMN BIC UNSET TAG DATA_SENSITIVITY;

-- -----------------------------------------------------
-- GOV1.4 Row access: users only see clients for their region
-- -----------------------------------------------------
CREATE OR REPLACE TABLE REGION_ENTITLEMENTS (ROLE_NAME STRING, CURRENCY STRING);
INSERT INTO REGION_ENTITLEMENTS VALUES
    ('HOL_RESTRICTED', 'GBP');      -- UK desk: sterling accounts only

CREATE OR REPLACE ROW ACCESS POLICY RAP_ACCOUNT_REGION AS (ACCT_CURRENCY STRING) RETURNS BOOLEAN ->
    IS_ROLE_IN_SESSION('HOL_PARTICIPANT')   -- lab builders see all
    OR EXISTS (SELECT 1 FROM BANKING_HOL.GOVERNANCE.REGION_ENTITLEMENTS e
               WHERE IS_ROLE_IN_SESSION(e.ROLE_NAME) AND e.CURRENCY = ACCT_CURRENCY);

ALTER TABLE ACCOUNT_REGISTER ADD ROW ACCESS POLICY RAP_ACCOUNT_REGION ON (CURRENCY);

-- (USAGE on the GOVERNANCE schema is granted to HOL_RESTRICTED by facilitator setup)
GRANT SELECT ON TABLE ACCOUNT_REGISTER TO ROLE HOL_RESTRICTED;

-- -----------------------------------------------------
-- GOV1.5 Test as each persona
-- -----------------------------------------------------
-- As the builder: all rows, but RESTRICTED values masked (not the data owner)
SELECT ACCOUNT_ID, CUSTOMER_NAME, CURRENCY, SORT_CODE, ACCOUNT_NUMBER, IBAN
FROM ACCOUNT_REGISTER ORDER BY ACCOUNT_ID LIMIT 8;

SELECT 'HOL_PARTICIPANT' AS AS_ROLE, COUNT(*) AS VISIBLE_ACCOUNTS FROM ACCOUNT_REGISTER;

-- As the restricted UK desk: GBP accounts only, masked
USE ROLE HOL_RESTRICTED;
SELECT ACCOUNT_ID, CUSTOMER_NAME, CURRENCY, SORT_CODE, ACCOUNT_NUMBER, IBAN
FROM BANKING_HOL.GOVERNANCE.ACCOUNT_REGISTER ORDER BY ACCOUNT_ID LIMIT 8;
SELECT 'HOL_RESTRICTED' AS AS_ROLE, COUNT(*) AS VISIBLE_ACCOUNTS FROM BANKING_HOL.GOVERNANCE.ACCOUNT_REGISTER;

USE ROLE HOL_PARTICIPANT;

-- -----------------------------------------------------
-- GOV1.6 Policies follow the data into AI
-- Ask CoCo or an agent built over ACCOUNT_REGISTER for "the IBAN for Royal Trust PLC":
-- the agent runs as YOUR role, so it only ever returns the masked value.
-- Bonus CoCo prompt:
--   "Show me every column in BANKING_HOL tagged DATA_SENSITIVITY and the
--    masking policy protecting it."
-- -----------------------------------------------------

-- In your bank: in production, tag + masking policies are owned by a central
-- governance role and applied to the Iceberg source tables themselves, so every
-- downstream view, dbt model, semantic view and agent inherits them automatically.

SELECT 'GOV1 complete' AS STATUS;

-- =====================================================
-- GOV4: Answer a customer's data request (solution / catch-up)
-- UK GDPR right of access: tag personal data once, find everything held about one customer,
-- show who read it, and log the response with its one-month due date.
-- Run as HOL_PARTICIPANT after GOV1. Works on copies in BANKING_HOL.GOVERNANCE (the sources stay read-only).
-- =====================================================
USE ROLE HOL_PARTICIPANT;
USE WAREHOUSE BANKING_WH;
USE SCHEMA BANKING_HOL.GOVERNANCE;

-- 1. Copies of the retail tables that hold customers
CREATE OR REPLACE TABLE RB_CUSTOMERS        AS SELECT * FROM BANKING_HOL.RAW_DATA.RB_CUSTOMERS;
CREATE OR REPLACE TABLE RB_ACCOUNTS         AS SELECT * FROM BANKING_HOL.RAW_DATA.RB_ACCOUNTS;
CREATE OR REPLACE TABLE RB_TRANSACTIONS     AS SELECT * FROM BANKING_HOL.RAW_DATA.RB_TRANSACTIONS;
CREATE OR REPLACE TABLE RB_CALL_TRANSCRIPTS AS SELECT * FROM BANKING_HOL.RAW_DATA.RB_CALL_TRANSCRIPTS;
CREATE OR REPLACE TABLE RB_COMPLAINTS       AS SELECT * FROM BANKING_HOL.RAW_DATA.RB_COMPLAINTS;
CREATE OR REPLACE TABLE RB_EMAILS           AS SELECT * FROM BANKING_HOL.RAW_DATA.RB_EMAILS;
CREATE OR REPLACE TABLE RB_FRAUD_CASES      AS SELECT * FROM BANKING_HOL.RAW_DATA.RB_FRAUD_CASES;
CREATE OR REPLACE TABLE RB_SAR_NARRATIVES   AS SELECT * FROM BANKING_HOL.RAW_DATA.RB_SAR_NARRATIVES;

-- 2. Tag personal data by kind, once
CREATE OR REPLACE TAG PERSONAL_DATA ALLOWED_VALUES 'IDENTITY', 'CONTACT', 'FINANCIAL', 'COMMUNICATIONS', 'FINANCIAL_CRIME'
  COMMENT = 'Which kind of personal data a column holds (UK GDPR right of access)';
ALTER TABLE RB_CUSTOMERS MODIFY
  COLUMN FIRST_NAME SET TAG PERSONAL_DATA = 'IDENTITY', COLUMN LAST_NAME SET TAG PERSONAL_DATA = 'IDENTITY',
  COLUMN DATE_OF_BIRTH SET TAG PERSONAL_DATA = 'IDENTITY', COLUMN ADDRESS_LINE_1 SET TAG PERSONAL_DATA = 'CONTACT',
  COLUMN POSTCODE SET TAG PERSONAL_DATA = 'CONTACT', COLUMN ANNUAL_INCOME_GBP SET TAG PERSONAL_DATA = 'FINANCIAL',
  COLUMN CREDIT_SCORE SET TAG PERSONAL_DATA = 'FINANCIAL';
ALTER TABLE RB_ACCOUNTS MODIFY COLUMN PRODUCT SET TAG PERSONAL_DATA = 'FINANCIAL', COLUMN BALANCE_GBP SET TAG PERSONAL_DATA = 'FINANCIAL';
ALTER TABLE RB_TRANSACTIONS MODIFY COLUMN AMOUNT_GBP SET TAG PERSONAL_DATA = 'FINANCIAL', COLUMN MERCHANT SET TAG PERSONAL_DATA = 'FINANCIAL';
ALTER TABLE RB_CALL_TRANSCRIPTS MODIFY COLUMN TRANSCRIPT SET TAG PERSONAL_DATA = 'COMMUNICATIONS';
ALTER TABLE RB_COMPLAINTS MODIFY COLUMN COMPLAINT_TEXT SET TAG PERSONAL_DATA = 'COMMUNICATIONS';
ALTER TABLE RB_EMAILS MODIFY COLUMN BODY SET TAG PERSONAL_DATA = 'COMMUNICATIONS';
ALTER TABLE RB_FRAUD_CASES MODIFY COLUMN INVESTIGATOR_NOTES SET TAG PERSONAL_DATA = 'FINANCIAL_CRIME';
ALTER TABLE RB_SAR_NARRATIVES MODIFY COLUMN NARRATIVE SET TAG PERSONAL_DATA = 'FINANCIAL_CRIME';

-- 3. Where does personal data live? (driven by the tags, not a hand-kept list)
SELECT 'RB_CUSTOMERS' AS TABLE_NAME, COLUMN_NAME, TAG_VALUE
FROM TABLE(BANKING_HOL.INFORMATION_SCHEMA.TAG_REFERENCES_ALL_COLUMNS('BANKING_HOL.GOVERNANCE.RB_CUSTOMERS', 'table'))
WHERE TAG_NAME = 'PERSONAL_DATA';

-- 4. The request log, with the legal due date (one month; up to two more for complex requests)
CREATE OR REPLACE TABLE DATA_REQUESTS (
    REQUEST_ID VARCHAR, CUSTOMER_ID VARCHAR, RECEIVED_AT TIMESTAMP_LTZ, DUE_BY DATE,
    TABLES_FOUND NUMBER, ROWS_FOUND NUMBER, HELD_BACK NUMBER, LETTER VARCHAR, PACK VARIANT
);

-- 5. One call answers a request: every tagged table holding the customer, financial crime
--    records held back for the MLRO, who read those tables in 30 days, and a drafted letter
CREATE OR REPLACE PROCEDURE DATA_REQUEST(CUSTOMER VARCHAR)
RETURNS VARIANT
LANGUAGE PYTHON
RUNTIME_VERSION = '3.11'
PACKAGES = ('snowflake-snowpark-python')
HANDLER = 'run'
AS
$$
import json, uuid

DB, SCH, TAG = "BANKING_HOL", "GOVERNANCE", "PERSONAL_DATA"
HELD = {"FINANCIAL_CRIME"}

def q(s):
    return '"' + s.replace('"', '""') + '"'

def run(session, customer):
    cust = session.sql(f"SELECT CUSTOMER_ID, FIRST_NAME || ' ' || LAST_NAME AS NAME FROM {DB}.{SCH}.RB_CUSTOMERS WHERE CUSTOMER_ID = ?",
                       params=[customer]).collect()
    if not cust:
        return {"error": f"No customer {customer}"}
    tables = [r["TABLE_NAME"] for r in session.sql(
        f"SELECT TABLE_NAME FROM {DB}.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = '{SCH}' AND COLUMN_NAME = 'CUSTOMER_ID' ORDER BY 1").collect()]
    found, held_back = [], []
    for t in tables:
        fqn = f"{DB}.{SCH}.{t}"
        tags = session.sql(f"SELECT COLUMN_NAME, TAG_VALUE FROM TABLE({DB}.INFORMATION_SCHEMA.TAG_REFERENCES_ALL_COLUMNS('{fqn}', 'table')) WHERE TAG_NAME = '{TAG}'").collect()
        if not tags:
            continue
        n = session.sql(f"SELECT COUNT(*) AS N FROM {fqn} WHERE CUSTOMER_ID = ?", params=[customer]).collect()[0]["N"]
        if n == 0:
            continue
        kinds = sorted({r["TAG_VALUE"] for r in tags})
        entry = {"table": t, "rows": n, "kinds": kinds}
        if HELD & set(kinds):
            held_back.append(entry)
            continue
        cols = ", ".join(f"LEFT({q(r['COLUMN_NAME'])}::VARCHAR, 200) AS {q(r['COLUMN_NAME'])}" for r in tags)
        entry["records"] = [r.as_dict() for r in session.sql(f"SELECT {cols} FROM {fqn} WHERE CUSTOMER_ID = ? LIMIT 50", params=[customer]).collect()]
        found.append(entry)
    names = "', '".join(f"{DB}.{SCH}.{e['table']}" for e in found + held_back)
    access = [r.as_dict() for r in session.sql(f"""
        WITH reads AS (
          SELECT DISTINCT ah.QUERY_ID, ah.USER_NAME, ah.QUERY_START_TIME
          FROM SNOWFLAKE.ACCOUNT_USAGE.ACCESS_HISTORY ah, LATERAL FLATTEN(ah.BASE_OBJECTS_ACCESSED) o
          WHERE ah.QUERY_START_TIME > DATEADD(day, -30, CURRENT_TIMESTAMP()) AND o.value:objectName::VARCHAR IN ('{names}'))
        SELECT USER_NAME, COUNT(*) AS QUERIES, TO_VARCHAR(MAX(QUERY_START_TIME), 'YYYY-MM-DD HH24:MI') AS LAST_READ
        FROM reads GROUP BY 1 ORDER BY QUERIES DESC""").collect()]
    rows = sum(e["rows"] for e in found)
    summary = "; ".join(f"{e['table']} ({e['rows']})" for e in found)
    letter = session.sql("SELECT AI_COMPLETE('claude-sonnet-4-5', ?) AS L", params=[
        f"Write a short plain-English cover letter (under 170 words, no markdown, no bracketed placeholders) from the bank to {cust[0]['NAME']} "
        f"answering their request for a copy of their personal data. Enclosed: {summary}. Say we searched every system that holds their "
        "personal data, there is no charge, and they can complain to the Information Commissioner's Office. Do not mention fraud, "
        "financial crime or anything held back. Sign off as the Data Protection Team."]).collect()[0]["L"]
    req = "DSR-" + uuid.uuid4().hex[:8].upper()
    pack = {"request_id": req, "customer": cust[0].as_dict(), "tables": found, "held_back": held_back, "access": access}
    session.sql(f"""INSERT INTO {DB}.{SCH}.DATA_REQUESTS
                    SELECT ?, ?, CURRENT_TIMESTAMP(), DATEADD(month, 1, CURRENT_DATE()), ?, ?, ?, ?, PARSE_JSON(?)""",
                params=[req, customer, len(found), rows, len(held_back), letter, json.dumps(pack, default=str)]).collect()
    return {"request_id": req, "tables": len(found), "rows": rows, "held_back": [e["table"] for e in held_back], "readers": len(access)}
$$;

-- 6. Answer one (RB101023 has a fraud case and a SAR, so two tables are held back)
CALL DATA_REQUEST('RB101023');
SELECT REQUEST_ID, CUSTOMER_ID, DUE_BY, TABLES_FOUND, ROWS_FOUND, HELD_BACK, LEFT(LETTER, 200) AS LETTER_START
FROM DATA_REQUESTS ORDER BY RECEIVED_AT DESC;

